# Public API (cmgr:*)
  @api cmgr:register(name, fn, undoDesc)  @ 126
      @contract  delegates to the global scope — root-level commands are gated-to-global, which is always reachable; the duplicated registration body now lives only in scope:register  @ 125
  @api cmgr:registerAll(tbl)  @ 127
  @api cmgr:rootKeymap()  @ 130
      @contract  returns the bottom-of-stack ('global') keymap directly — used by dispatchers that want to fire ONLY root bindings (e.g. trackerPage's swing editor wants playPause/quit live but page-scoped commands off)  @ 129
  @api cmgr:bind(name, keys)  @ 132
  @api cmgr:bindAll(tbl)  @ 133
  @api cmgr:installManifest(manifest, ImGui)  @ 145-176
      @contract  parses tokens into the keymap, stamps entry.group, sets scope.manifest to the groups  @ 144
  @api cmgr:entry(name)  @ 179-183
      @contract  raises on a name no manifest declares, so a consumer naming a stale command fails loudly  @ 178
  @api cmgr:surface()  @ 188-198
      -- What a page can reach: the union of scopes-on-stack manifests, filtered by the modal
      -- rule invoke gates on. Buckets by entry.group; a scope off the stack contributes nothing.
      @contract  reachable entries, bottom of stack first, each group's entries in declaration order  @ 187
  @api cmgr:auditManifests()  @ 202-227
      @contract  a declared scope's entries and its registrations must correspond, both ways  @ 200
      @contract  a scope that registers a command while declaring no manifest raises  @ 201
  @api cmgr:installTree(tree)  @ 307-326
      @contract  stamps node letters, each pathed entry's title/letter/node; runs after installManifest  @ 306
  @api cmgr:wrap(name, wrapper)  @ 329-333
      @contract  wrap is a no-op if name has no registered command; wrappers stack (compose outward)  @ 328
  @api cmgr:doBefore(name, before)  @ 338-346
      @contract  doBefore/doAfter accept either a single name or an array of names  @ 335
      @contract  doAfter preserves the original command's return values (the dispatch signal)  @ 336
      @invariant  wraps compose inside the gate — when invoke skips a gated command, no doBefore / doAfter side-effect fires  @ 337
  @api cmgr:doAfter(name, after)  @ 348-358
  @api cmgr:beginPrefix()  @ 380
      @contract  buffer accepts only '0'..'9' and '/'; cancel/finish/invoke each leave the state inactive  @ 379
  @api cmgr:isPrefixActive()  @ 381
  @api cmgr:appendPrefix(ch)  @ 383-387
  @api cmgr:cancelPrefix()  @ 389
  @api cmgr:finishPrefix()  @ 392-410
      @contract  empty buffer or unparseable input → nil pending value; '/' with empty numerator or denominator parses as nil; integer N stored as (N/1)  @ 391
  @api cmgr:prefixRational()  @ 413-415
      @contract  non-consuming reader of the parsed rational; safe to call inside a command body. Returns (nil, nil) when no prefix is pending. State is cleared at the end of invoke, not by this call.  @ 412
  @api cmgr:scope(name)  @ 420-427
      @contract  creates the scope on first request; idempotent thereafter  @ 419
  @api cmgr:push(s)  @ 432-436
      @contract  push(name|scope); creates a named scope if absent. Top-of-stack is the most recently pushed.  @ 431
  @api cmgr:pop(s)  @ 439-443
      @contract  pop(name|scope) asserts the named scope is currently on top; pops it  @ 438
  @api cmgr:lastCommand()  @ 451
      @contract  name and serial of the last body run; unknown or gated-out changes neither  @ 450
  @api cmgr:invoke(name, ...)  @ 456-476
      @contract  returns nil when the command is unknown OR registered on a scope that is not currently reachable (off-stack or blocked by a modal above)  @ 453
      @contract  always prepends the pending prefix (defaulted to 1 when nothing is pending) as the first argument to the command body. Bodies that need to distinguish "user typed 1" from "no prefix" read prefixRational() — it returns (nil, nil) when nothing is pending. State stays live for the call so the body may read it; cleared on return ONLY if there was a pending prefix at entry, so a command body that opens prefix mode (beginPrefix) is not wiped out by its own invoke.  @ 454
      @contract  spring-loaded scope: redirect[] runs fn in-place; keepAlive[] passes; else onBail()  @ 455
  @api cmgr:keysFor(name)  @ 492
  @api cmgr:keychain()  @ 495-512
      @contract  returns one keymap per stack scope in top-down order; modal scopes filter lower keymaps to their passthrough name set, then halt the walk  @ 494
  @api cmgr:keySpec(spec, ImGui)  @ 515-520
      -- ImGui injected so cmgr stays free of REAPER-side imports at module load.
  @api cmgr:commandAtKey(spec, exceptName, ImGui)  @ 526-538
      @contract  reachable command for spec's key (keychain top-down); skips exceptName; nil if free  @ 525
  @api cmgr:bindingSite(name)  @ 541-548
      @contract  scope to edit name's binding in: scope currently binding it, else its gate scope  @ 540
  @api cmgr:noteChars(char)  @ 554-556
      -- Re-read noteLayout on each call so a config change takes effect
      -- without rebuilding vm.
  @api cmgr:keyLabel(spec, ImGui)  @ 643-655
  @api cmgr:keyLabelList(name, ImGui)  @ 658-664
      @contract  list of human labels, one per bound keyspec of the reachable command, or nil if unbound  @ 657
  @api cmgr:keyLabels(name, ImGui)  @ 667-670
      @contract  keyLabelList joined by ' / ', or nil if unbound on the current stack  @ 666
  @api cmgr:tokenForSpec(spec, ImGui)  @ 732-743
      @contract  spec -> stable ASCII token ("Ctrl+Z"); nil if the key has no token name  @ 731
  @api cmgr:specForToken(token, ImGui)  @ 746-761
      @contract  token -> keyspec (bare key | {key, mod...}); (nil, err) on an unknown key/modifier  @ 745
  @api cmgr:loadOverrides(ImGui)  @ 767-782
      @contract  a malformed token is warned and skipped; the command keeps its other (good) bindings  @ 766
  @api cmgr:rebind(scopeName, name, specs, ImGui)  @ 785-795
      @contract  overwrites the scope's binding for name and persists it as tokens (global tier)  @ 784
  @api cmgr:familyVictim(family, mods, ImGui)  @ 818-829
      @contract  (victim, spec) for the first proposed chord already spoken for; nil if the mask is free  @ 816
      @invariant  a family's own members are never victims — a rebind vacates their chords wholesale  @ 817
  @api cmgr:rebindFamily(family, mods, ImGui)  @ 832-836
      @contract  rewrites every member to its base token under mods, one binding each, live + persisted  @ 831

